 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private YouTubeActivity activity;private Activity companion;private String phase="launch";
 private Object field(String name)throws Exception{Field f=YouTubeActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{boolean[] ready={false};for(int i=0;i<300;i++){ins.runOnMainSync(()->{try{ready[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])return;Thread.sleep(50);}try{Bitmap shot=captureEnabled()?ins.getUiAutomation().takeScreenshot():null;if(shot!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"youtube-fullscreen-failure.png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);shot.recycle();}report("failure",new JSONObject().put("phase",phase).put("page",js((WebView)unchecked("web"),"JSON.stringify({title:document.title,clicked:window.__clicked,error:window.__fullError,enabled:document.fullscreenEnabled,element:!!document.fullscreenElement})")));}catch(Exception ignored){}fail("YouTube fullscreen scenario timed out: "+phase);}
 private void launch(){activity=(YouTubeActivity)ins.startActivitySync(new Intent(c,YouTubeActivity.class).putExtra(YouTubeFavorites.EXTRA,"https://m.youtube.com/watch?v=aqz-KE-bpKQ").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 @After public void after(){if(companion!=null){Activity old=companion;ins.runOnMainSync(old::finish);ins.waitForIdleSync();companion=null;}if(activity!=null){ins.runOnMainSync(activity::finish);ins.waitForIdleSync();}}
 private void report(String part,JSONObject value)throws Exception{try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"youtube-fullscreen-"+part+".json"))){out.write(value.toString(2).getBytes("UTF-8"));}}
 @Test public void realHtmlVideoEntersFullscreenAndBackRestoresSameBrowser()throws Exception{launch();waitFor(()->field("web")!=null);WebView[] browser={null};int[] originalOrientation={0};ins.runOnMainSync(()->{try{browser[0]=(WebView)field("web");originalOrientation[0]=activity.getRequestedOrientation();WebViewClient delegate=browser[0].getWebViewClient();browser[0].stopLoading();browser[0].setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest request){try{if(request.getUrl().getPath().endsWith(".mp4"))return new WebResourceResponse(webmFixture()?"video/webm":"video/mp4",null,ins.getContext().getAssets().open(webmFixture()?"fullscreen.webm":"combined.mp4"));String html="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Onda fullscreen fixture</title></head><body style='margin:0'><button id='full' style='width:100%;height:80px' onclick=\"window.__clicked=event.isTrusted;var v=document.querySelector('video');v.play();try{var request=v.requestFullscreen();if(request)request.catch(function(e){window.__fullError=String(e);});}catch(e){window.__fullError=String(e);}\">Assistir em tela cheia</button><video style='width:100%' playsinline controls loop src='https://m.youtube.com/onda-fullscreen.mp4'></video></body></html>";return new WebResourceResponse("text/html","UTF-8",new ByteArrayInputStream(html.getBytes("UTF-8")));}catch(Exception e){throw new RuntimeException(e);}}@Override public void onPageFinished(WebView w,String url){delegate.onPageFinished(w,url);}});browser[0].loadUrl("https://m.youtube.com/watch?v=aqz-KE-bpKQ");}catch(Exception e){throw new RuntimeException(e);}});phase="fixture";android.util.Log.i("OndaFullscreenTest","fixture");waitFor(()->"Onda fullscreen fixture".equals(browser[0].getTitle())&&browser[0].getProgress()==100&&activity.hasWindowFocus()&&browser[0].getWidth()>0);java.util.concurrent.CountDownLatch painted=new java.util.concurrent.CountDownLatch(1);ins.runOnMainSync(()->browser[0].postVisualStateCallback(1,new WebView.VisualStateCallback(){@Override public void onComplete(long id){painted.countDown();}}));assertTrue("Fixture did not paint",painted.await(10,java.util.concurrent.TimeUnit.SECONDS));Thread.sleep(300);JSONArray position=new JSONArray(js(browser[0],"(function(){var r=document.getElementById('full').getBoundingClientRect();return [r.left+r.width/2,r.top+r.height/2,innerWidth];})()"));int[] point=new int[2];float[] scale={1};ins.runOnMainSync(()->{browser[0].getLocationOnScreen(point);scale[0]=browser[0].getWidth()/(float)position.optDouble(2,1);});float x=point[0]+(float)position.getDouble(0)*scale[0],y=point[1]+(float)position.getDouble(1)*scale[0];phase="fullscreen";android.util.Log.i("OndaFullscreenTest","fullscreen gesture");long now=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent event=MotionEvent.obtain(now,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);assertTrue(ins.getUiAutomation().injectInputEvent(event,true));event.recycle();Thread.sleep(80);}waitFor(()->field("fullscreenView")!=null&&activity.hasWindowFocus()&&((View)field("fullscreen")).getWidth()==activity.getWindow().getDecorView().getWidth()&&activity.getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE);phase="video-playing";android.util.Log.i("OndaFullscreenTest","video-playing wait");boolean moving=false;for(int retry=0;retry<100;retry++){if("true".equals(js(browser[0],"(function(){var v=document.querySelector('video');return !!document.fullscreenElement&&v.readyState>=2&&!v.paused&&v.currentTime>.5;})()"))){moving=true;break;}Thread.sleep(50);}assertTrue("HTML video did not advance in fullscreen",moving);android.util.Log.i("OndaFullscreenTest","video advancing; tutorial");dismissImmersiveTutorial();Thread.sleep(300);android.util.Log.i("OndaFullscreenTest","tutorial handled; capture="+captureEnabled());ins.runOnMainSync(()->{try{assertSame(browser[0],field("web"));assertEquals(View.GONE,((View)field("page")).getVisibility());View full=(View)field("fullscreen");assertTrue(full.getWidth()>=activity.getWindow().getDecorView().getWidth()-2);assertTrue((activity.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_FULLSCREEN)!=0);assertTrue((activity.getWindow().getDecorView().getSystemUiVisibility()&View.SYSTEM_UI_FLAG_HIDE_NAVIGATION)!=0);}catch(Exception e){throw new RuntimeException(e);}});Bitmap shot=captureEnabled()?ins.getUiAutomation().takeScreenshot():null;if(shot!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"youtube-fullscreen.png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);shot.recycle();}android.util.Log.i("OndaFullscreenTest","capture finished");phase="picture-in-picture";js(browser[0],"window.__ondaPipTicks=0;document.querySelector('video').addEventListener('timeupdate',function(){window.__ondaPipTicks++;});true");assertTrue(ins.getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_HOME));waitFor(()->activity.isInPictureInPictureMode()&&field("web")==browser[0]&&field("fullscreenView")!=null);boolean pipMoving=false;for(int retry=0;retry<100;retry++){if("true".equals(js(browser[0],"(function(){var v=document.querySelector('video');return window.__ondaPipTicks>=2&&!v.paused&&v.readyState>=2;})()"))){pipMoving=true;break;}Thread.sleep(50);}assertTrue("HTML video stopped while visible in Android PiP",pipMoving);phase="pip-other-webview";companion=ins.startActivitySync(new Intent(c,ImageSearchActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK));ins.waitForIdleSync();assertTrue("Other Onda page unexpectedly removed PiP",activity.isInPictureInPictureMode());Activity closed=companion;ins.runOnMainSync(closed::finish);ins.waitForIdleSync();companion=null;js(browser[0],"window.__ondaPipTicks=0;true");assertVideoStillAdvancing(browser[0]);report("pip",new JSONObject().put("actualAndroidPictureInPicture",true).put("homeKeepsSameBrowser",true).put("htmlVideoTimeUpdatesInPip",true).put("closingOtherWebViewKeepsPipActive",true));Thread.sleep(2000);ins.runOnMainSync(()->c.startActivity(new Intent(c,YouTubeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));waitFor(()->!activity.isInPictureInPictureMode()&&activity.hasWindowFocus()&&field("web")==browser[0]&&field("fullscreenView")!=null);phase="back";assertTrue(ins.getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK));waitFor(()->field("fullscreenView")==null&&((View)field("page")).getVisibility()==View.VISIBLE);android.util.Log.i("OndaFullscreenTest","back restored page");ins.runOnMainSync(()->{assertSame(browser[0],unchecked("web"));assertEquals(originalOrientation[0],activity.getRequestedOrientation());assertFalse(activity.isFinishing());});String previous="https://m.youtube.com/watch?v=aqz-KE-bpKQ",next="https://m.youtube.com/watch?v=i7j0bw5TonI";ins.runOnMainSync(()->browser[0].loadUrl(next));waitFor(()->next.equals(browser[0].getUrl())&&browser[0].getProgress()==100&&browser[0].canGoBack());assertTrue(ins.getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK));waitFor(()->previous.equals(browser[0].getUrl()));assertFalse(activity.isFinishing());report("video",new JSONObject().put("realHtmlVideoRequest",true).put("realTouchGesture",true).put("landscapeWithoutBrowserRecreation",true).put("actualVideoPlayingInFullscreen",true).put("appControlsAndSystemBarsHidden",true).put("backRestoresSameBrowser",true).put("normalBackRestoresHistory",true).put("pictureInPictureKeepsVideoMoving",true).put("returnFromPipPreservesBrowser",true));}
 private void assertVideoStillAdvancing(WebView browser)throws Exception{for(int retry=0;retry<100;retry++){if("true".equals(js(browser,"(function(){var v=document.querySelector('video');return window.__ondaPipTicks>=2&&!v.paused&&v.readyState>=2;})()")))return;Thread.sleep(50);}String state=js(browser,"JSON.stringify((function(){var v=document.querySelector('video');return {ticks:window.__ondaPipTicks,paused:v.paused,readyState:v.readyState,currentTime:v.currentTime,visibility:document.visibilityState,ended:v.ended,error:v.error?v.error.code:null};})())");report("failure",new JSONObject().put("phase",phase).put("video",state).put("nativePip",activity.isInPictureInPictureMode()).put("sameBrowser",field("web")==browser).put("fullscreenRetained",field("fullscreenView")!=null));fail("Closing another web page suspended PiP video: "+state);}
 private boolean webmFixture(){return "true".equals(androidx.test.platform.app.InstrumentationRegistry.getArguments().getString("fullscreen_webm","false"));}
 private boolean captureEnabled(){return !"true".equals(androidx.test.platform.app.InstrumentationRegistry.getArguments().getString("skip_fullscreen_capture","false"));}
 private void dismissImmersiveTutorial()throws Exception{android.accessibilityservice.AccessibilityServiceInfo info=ins.getUiAutomation().getServiceInfo();int old=info.flags;info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;ins.getUiAutomation().setServiceInfo(info);try{for(int retry=0;retry<35;retry++){java.util.ArrayList<android.view.accessibility.AccessibilityNodeInfo> roots=new java.util.ArrayList<>();android.view.accessibility.AccessibilityNodeInfo active=ins.getUiAutomation().getRootInActiveWindow();if(active!=null)roots.add(active);for(android.view.accessibility.AccessibilityWindowInfo window:ins.getUiAutomation().getWindows()){android.view.accessibility.AccessibilityNodeInfo root=window.getRoot();if(root!=null)roots.add(root);}for(android.view.accessibility.AccessibilityNodeInfo root:roots)for(String text:new String[]{"GOT IT","ENTENDI"})for(android.view.accessibility.AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(text)){android.view.accessibility.AccessibilityNodeInfo target=node;for(int parent=0;parent<5&&target!=null;parent++,target=target.getParent())if(target.isClickable()&&target.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK)){Thread.sleep(350);return;}}Thread.sleep(100);}}finally{info.flags=old;ins.getUiAutomation().setServiceInfo(info);}}
 private String js(WebView view,String code)throws Exception{java.util.concurrent.CountDownLatch latch=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicReference<String> result=new java.util.concurrent.atomic.AtomicReference<>();ins.runOnMainSync(()->view.evaluateJavascript(code,value->{result.set(value);latch.countDown();}));assertTrue(latch.await(5,java.util.concurrent.TimeUnit.SECONDS));return result.get();}
 private Object unchecked(String name){try{return field(name);}catch(Exception e){throw new RuntimeException(e);}}
 @Test public void duplicateRequestsAndLeavingScreenReleaseFullscreenExactlyOnce()throws Exception{launch();waitFor(()->field("web")!=null);AtomicInteger first=new AtomicInteger(),duplicate=new AtomicInteger();int[] flags={0},orientation={0},ui={0};ins.runOnMainSync(()->{try{WebView web=(WebView)field("web");web.stopLoading();flags[0]=activity.getWindow().getAttributes().flags;orientation[0]=activity.getRequestedOrientation();ui[0]=activity.getWindow().getDecorView().getSystemUiVisibility();WebChromeClient chrome=web.getWebChromeClient();chrome.onShowCustomView(new FrameLayout(activity),first::incrementAndGet);chrome.onShowCustomView(new FrameLayout(activity),duplicate::incrementAndGet);assertEquals(1,duplicate.get());assertEquals(0,first.get());Method pause=YouTubeActivity.class.getDeclaredMethod("onPause");pause.setAccessible(true);pause.invoke(activity);assertNull(field("fullscreenView"));assertNull(field("fullscreenBackCallback"));assertEquals(1,first.get());chrome.onHideCustomView();assertEquals(1,first.get());assertEquals(orientation[0],activity.getRequestedOrientation());int mask=WindowManager.LayoutParams.FLAG_FULLSCREEN|WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON;assertEquals(flags[0]&mask,activity.getWindow().getAttributes().flags&mask);assertEquals(ui[0],activity.getWindow().getDecorView().getSystemUiVisibility());Method resume=YouTubeActivity.class.getDeclaredMethod("onResume");resume.setAccessible(true);resume.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}});report("lifecycle",new JSONObject().put("duplicateRequestDismissed",true).put("exitCallbackExactlyOnce",true).put("screenAwakeFlagRestored",true).put("orientationAndSystemUiRestored",true));}
